const { data, error, refresh } = await useFetch<Record<string, any>>(() => '/api/w/me' + q.value, { key: 'w-me' })
const router = useRouter()
const tab = computed({ get: () => String(route.query.t ?? 'home'), set: (v: string) => { void router.replace({ query: { ...route.query, t: v === 'home' ? undefined : v } }) } })
// Still in the onboarding conversation (or waiting for approval): that comes first.
if (!route.query.client && data.value?.onboarding && data.value.onboarding !== 'done') await navigateTo('/w/start', { replace: true })
// Private deals the Aidi team is offering clients: say you are interested, with an amount.
interface Deal { website: string | null; logo_doc_id: string | null; about: string | null; id: string; company: string; title: string; sector: string | null; stage: string | null; lead: string | null; co_investors: string | null; min_investment: number | null; valuation: string | null; currency: string; received: string; closes_at: string | null; closed: boolean; my_status: string | null; my_amount: number | null }
const { data: deals, refresh: refreshDeals } = await useFetch<{ deals: Deal[]; room?: { accredited: boolean; cap: number; now_pct: number; room: number; level: string | null } }>(() => '/api/w/secondaries' + q.value, { key: 'w-deals', default: () => ({ deals: [] }) })
const di = reactive({ id: '', amount: '' as string | number, note: '', busy: false, msg: '' })
// "Not for me": this viewer's own choice, kept in their browser; passed deals sink to the end, dimmed.
const hidden = ref<string[]>([])
onMounted(() => { try { hidden.value = JSON.parse(localStorage.getItem('deal-pass') || '[]') } catch { hidden.value = [] } })
function passDeal(d: Deal) { hidden.value = hidden.value.includes(d.id) ? hidden.value.filter((x) => x !== d.id) : [...hidden.value, d.id]; if (di.id === d.id) di.id = ''; try { localStorage.setItem('deal-pass', JSON.stringify(hidden.value)) } catch { /* private window */ } }
const shownDeals = computed(() => [...(deals.value?.deals ?? [])].sort((a, b) => Number(hidden.value.includes(a.id)) - Number(hidden.value.includes(b.id))))
function wantIn(d: Deal) { Object.assign(di, { id: d.id, amount: d.my_amount ?? d.min_investment ?? '', note: '', busy: false, msg: '' }) }
async function sendInterest(action: 'interested' | 'withdraw', id = di.id) { if (route.query.client) { di.msg = 'Preview only.'; return } di.busy = true; di.msg = ''; try { await $fetch('/api/w/secondaries', { method: 'POST', body: { id, action, amount: di.amount, note: di.note } }); di.id = ''; await refreshDeals() } catch (e) { di.msg = (e as { data?: { data?: { error?: { message?: string } } } }).data?.data?.error?.message ?? 'Could not send.' } finally { di.busy = false } }
const closesTxt = (d: Deal) => { if (d.closed) return 'Closed'; if (!d.closes_at) return ''; const n = Math.round((new Date(d.closes_at + 'T00:00:00Z').getTime() - new Date(new Date().toISOString().slice(0, 10) + 'T00:00:00Z').getTime()) / 86400e3); return n <= 0 ? 'Closes today' : 'Closes in ' + n + ' day' + (n === 1 ? '' : 's') }
