const investing = computed(() => !!(data.value?.features?.savings || data.value?.features?.trading || data.value?.features?.wallet))
const investApi = computed(() => (!investing.value ? null : preview.value ? '/api/wm/clients/' + route.query.client + '/invest' : '/api/w/invest'))
