const sg = reactive({ doc: null as { id: string; title: string } | null, name: '', sig: '', agree: false, busy: false, msg: '' })
async function sign() { sg.busy = true; sg.msg = ''; try { await $fetch('/api/w/docs', { method: 'POST', body: { action: 'sign', doc_id: sg.doc!.id, name: sg.name, signature: sg.sig, agree: sg.agree } }); sg.doc = null; await refreshDocs() } catch (e) { sg.msg = (e as { data?: { data?: { error?: { message?: string } } } }).data?.data?.error?.message ?? 'Could not sign.' } finally { sg.busy = false } }
async function decline() { const reason = await askPrompt('Tell us why you are declining (optional):') ?? ''; await $fetch('/api/w/docs', { method: 'POST', body: { action: 'decline', doc_id: sg.doc!.id, reason } }); sg.doc = null; await refreshDocs() }
const { data: fees } = await useFetch<{ id: string; number: string; kind: string; period: string | null; amount: number; currency: string; status: string; paid_on: string | null; invoice_doc_id: string | null; receipt_doc_id: string | null; pay_url: string | null }[]>('/api/w/fees', { key: 'w-fees', default: () => [] })
const money = (v: number | string | null, c: string) => (v == null ? '—' : new Intl.NumberFormat('en-US', { style: 'currency', currency: c, maximumFractionDigits: 0 }).format(Number(v)))
const fm = reactive({ name: '', relationship: '', email: '' }); const link = ref(''); const msg = ref('')
