          :star-label="d.my_status === 'invested' ? 'Invested' : d.my_status === 'interested' ? 'Interested · change amount' : 'I\'m interested'" pass-label="Not for me" @star="!d.closed && d.my_status !== 'invested' && wantIn(d)" @pass="passDeal(d)">
          <p v-if="d.my_status === 'invested' || d.my_status === 'interested'" class="ab2 mut">{{ d.my_status === 'invested' ? 'Invested' : 'You said you are interested' }}{{ d.my_amount ? ' · ' + usd0(d.my_amount) : '' }}<button v-if="d.my_status === 'interested'" class="lk" @click="sendInterest('withdraw', d.id)">Withdraw</button></p>
