        </DealCard></div></div>
      <div v-else-if="tab === 'statements'" class="card"><h3>Statements</h3><div v-for="s in statements" :key="s.id" class="rw"><span><b>{{ s.label }}</b><span class="mut"> · {{ s.period_kind }} · ending value {{ money(s.ending, 'USD') }}</span></span><span class="fa"><a :href="'/api/w/statements/' + s.id + '?mode=view'" target="_blank">View</a><a :href="'/api/w/statements/' + s.id + '?mode=download'">Download PDF</a></span></div><p v-if="!statements?.length" class="mut">Your statements will appear here.</p></div>
